import { bootstrapApplication } from '@angular/platform-browser';
import { ChangeDetectorRef, Component, OnInit, inject, provideZoneChangeDetection } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { NavigationEnd, provideRouter, Router, RouterLink, RouterOutlet, Routes } from '@angular/router';
import { filter } from 'rxjs';
import { provideHttpClient } from '@angular/common/http';
import { ApiService } from './api.service';

const msg = (error: any) => error?.error?.message ?? 'No fue posible completar la operación.';

@Component({ selector: 'ticket-app', standalone: true, imports: [CommonModule, RouterLink, RouterOutlet], template: `
  <ng-container *ngIf="isLogin; else shell"><router-outlet /></ng-container>
  <ng-template #shell><ng-container *ngIf="authReady && authenticated; else loading">
    <div class="main-wrapper"><aside class="sidebar"><nav class="menu">
      <a class="menu-item" routerLink="/home"><i class="bi bi-house"></i><span class="tooltip">Home</span></a>
      <a class="menu-item" *ngIf="roleId===2||roleId===4" routerLink="/tickets"><i class="bi bi-card-checklist"></i><span class="tooltip">{{roleId===4?'Asignar Tickets':'Mis Tickets Asignados'}}</span></a>
      <a class="menu-item" routerLink="/nuevo-ticket"><i class="bi bi-plus-circle"></i><span class="tooltip">Mis Tickets / Crear</span></a>
      <a class="menu-item" routerLink="/calendario"><i class="bi bi-calendar-event"></i><span class="tooltip">Calendario</span></a>
      <a class="menu-item" *ngIf="roleId===3" routerLink="/estadisticas"><i class="bi bi-graph-up"></i><span class="tooltip">Estadísticas</span></a>
      <a class="menu-item" *ngIf="roleId===3" routerLink="/usuarios"><i class="bi bi-people-fill"></i><span class="tooltip">Gestionar usuarios</span></a>
      <a class="menu-item" *ngIf="roleId===3" routerLink="/areas"><i class="bi bi-building"></i><span class="tooltip">Gestionar áreas</span></a>
      <a class="menu-item" routerLink="/acercade"><i class="bi bi-info-circle"></i><span class="tooltip">Acerca de</span></a>
    </nav><div class="profile" (click)="dropdown = !dropdown"><i class="bi bi-person-circle" style="font-size:2rem"></i><div class="dropdown-menu" [class.show]="dropdown"><a routerLink="/perfil">Mi perfil</a><a href="#" (click)="$event.preventDefault(); logout()">Salir</a></div></div></aside>
    <main class="main-content with-sidebar"><div class="container body-content"><router-outlet /></div></main></div>
  </ng-container><ng-template #loading><div class="text-center p-5" *ngIf="!authReady">Cargando tu sesión…</div></ng-template></ng-template>` })
class AppComponent implements OnInit {
  private router = inject(Router); private api = inject(ApiService); private cdr = inject(ChangeDetectorRef);
  isLogin = location.pathname === '/' || location.pathname === '/login'; dropdown = false; roleId = 0; authReady = false; authenticated = false;
  ngOnInit() { this.router.events.pipe(filter(event => event instanceof NavigationEnd)).subscribe(() => this.isLogin = this.router.url.startsWith('/login') || this.router.url === '/'); window.addEventListener('ticket-session-updated', () => void this.loadSession()); void this.loadSession(); }
  private async loadSession() { this.authReady = false; try { const user = await this.api.get<any>('/auth/me'); this.roleId = Number(user.roleId); this.authenticated = true; this.authReady = true; this.cdr.detectChanges(); if (this.isLogin) await this.router.navigateByUrl('/home'); } catch { this.roleId = 0; this.authenticated = false; this.authReady = true; this.cdr.detectChanges(); if (!this.isLogin) await this.router.navigateByUrl('/login'); } }
  async logout() { try { await this.api.post('/auth/logout'); this.authenticated = false; this.roleId = 0; window.location.replace('/login'); } catch { alert('No se pudo cerrar la sesión con el servidor. Revisa que el backend esté en ejecución e inténtalo de nuevo.'); } }
}

@Component({ selector: 'login-page', standalone: true, imports: [CommonModule, FormsModule], styleUrls: ['./legacy-styles/iniciosesion.css'], template: `
<main class="login-main"><img src="/assets/Img/logo.png" alt="Logo" class="logo-img"><div class="contenedor-formularios">
  <ul class="contenedor-tabs"><li class="tab tab-segunda" [class.active]="!register"><a href="#iniciar-sesion" (click)="$event.preventDefault();register=false">Iniciar Sesión</a></li><li class="tab tab-primera" [class.active]="register"><a href="#registrarse" (click)="$event.preventDefault();register=true">Registrarse</a></li></ul>
  <div class="contenido-tab">
    <div class="alert alert-success" *ngIf="notice">{{notice}}</div><div class="alert alert-warning" *ngIf="error">{{error}}</div>
    <section *ngIf="!register" id="iniciar-sesion"><h1>Iniciar Sesión</h1><form (ngSubmit)="login()"><div class="contenedor-input ajuste-titulo"><label>Correo Electrónico <span class="req">*</span></label><input class="form-input" type="email" [(ngModel)]="email" name="email" required></div><div class="contenedor-input ajuste-titulo"><label>Contraseña <span class="req">*</span></label><input class="form-input" type="password" [(ngModel)]="password" name="password" required></div><button type="submit" class="button button-block" [disabled]="busy">{{busy?'Validando…':'Ingresar'}}</button></form></section>
    <section *ngIf="register" id="registrarse"><h1>Registrarse</h1><form (ngSubmit)="signup()"><div class="fila-arriba"><div class="contenedor-input"><label>Nombre(s) <span class="req">*</span></label><input class="form-input" [(ngModel)]="form.name" name="name" required></div><div class="contenedor-input"><label>Apellidos <span class="req">*</span></label><input class="form-input" [(ngModel)]="form.lastName" name="lastName" required></div></div><div class="contenedor-input"><label>Correo Electrónico <span class="req">*</span></label><input class="form-input" type="email" [(ngModel)]="form.email" name="registerEmail" required></div><div class="contenedor-input ajuste-titulo"><label>Área <span class="req">*</span></label><select class="form-input" [(ngModel)]="form.departmentId" name="departmentId" required><option [ngValue]="null">Seleccione...</option><option *ngFor="let a of areas" [ngValue]="a.id_Departamento">{{a.dep_Nombre}}</option></select></div><div class="contenedor-input"><label>Número de Contacto <span class="req">*</span></label><input class="form-input" [(ngModel)]="form.phone" name="phone" maxlength="15" required></div><div class="contenedor-input"><label>Contraseña <span class="req">*</span></label><input class="form-input" type="password" [(ngModel)]="form.password" name="newPassword" required></div><div class="contenedor-input"><label>Confirmar contraseña <span class="req">*</span></label><input class="form-input" type="password" [(ngModel)]="form.confirmPassword" name="confirmPassword" required></div><button type="submit" class="button button-block" [disabled]="busy">{{busy?'Registrando…':'Registrar'}}</button></form></section>
  </div></div></main>` })
class LoginComponent implements OnInit {
  private api=inject(ApiService); private router=inject(Router); register=false; busy=false; error=''; notice=''; email=''; password=''; areas:any[]=[];
  form:any={name:'',lastName:'',email:'',phone:'',departmentId:null,password:'',confirmPassword:''};
  async ngOnInit(){try{this.areas=(await this.api.get<any>('/lookups')).departments;}catch{}}
  async login(){if(this.busy)return;this.busy=true;this.error='';this.notice='';try{await this.api.post('/auth/login',{email:this.email,password:this.password});await this.api.get('/auth/me');window.dispatchEvent(new Event('ticket-session-updated'));await this.router.navigateByUrl('/home');}catch(e:any){this.error=e?.status===401?'Su contraseña o correo son incorrectos.':msg(e);}finally{this.busy=false;}}
  async signup(){if(this.busy)return;this.error='';this.notice='';const email=String(this.form.email??'').trim();if(!this.form.name?.trim()||!this.form.lastName?.trim()||!email||!String(this.form.phone??'').trim()||!this.form.departmentId){this.error='Completa todos los campos y selecciona un área.';return;}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){this.error='Escribe un correo electrónico válido.';return;}if(this.form.password.length<8||this.form.password!==this.form.confirmPassword){this.error='La contraseña debe tener al menos 8 caracteres y coincidir con su confirmación.';return;}this.busy=true;try{await this.api.post('/auth/register',{...this.form,email});await this.api.get('/auth/me');window.dispatchEvent(new Event('ticket-session-updated'));await this.router.navigateByUrl('/home');}catch(e){this.error=msg(e);}finally{this.busy=false;}}
}

@Component({selector:'dashboard-page',standalone:true,imports:[CommonModule],styleUrls:['./legacy-styles/home.css'],template:`
<section class="dashboard"><h2 class="profile-title">{{welcomeName?'¡Bienvenido de nuevo, '+welcomeName+'!':'Inicio'}}</h2><div class="alert alert-info" *ngIf="loading">Cargando la información de tu rol…</div><div class="alert alert-danger" *ngIf="error">{{error}}</div><div class="row g-3" *ngIf="!loading"><div class="col-md-4" *ngFor="let card of cards"><div class="stat-card tickets p-3"><div class="stat-value">{{card.value}}</div><div>{{card.label}}</div></div></div></div><div class="chart-container mt-3"><h5>Mi creación de tickets en la semana</h5><div class="d-flex align-items-end gap-2 chart-bars"><div *ngFor="let item of chart" class="chart-bar" [style.height.%]="bar(item)" [title]="item.totalTickets+' tickets'"><span>{{item.totalTickets}}</span><small>{{item.diaSemana}}</small></div></div></div><div class="tickets-list-container"><h5>Mis últimos tickets creados</h5><div class="ticket-item" *ngFor="let t of recent"><div class="ticket-id">#{{t.id}}</div><div class="ticket-content"><b>{{t.titulo}}</b><div class="ticket-desc">{{t.descripcion}}</div></div><span class="status-badge">{{t.estado}}</span></div><p *ngIf="!recent.length">No hay tickets recientes.</p></div></section>`})
class DashboardComponent implements OnInit { private api=inject(ApiService); private cdr=inject(ChangeDetectorRef); cards:any[]=[]; chart:any[]=[]; recent:any[]=[]; loading=true; error=''; welcomeName=''; async ngOnInit(){try{const me=await this.api.get<any>('/auth/me');this.welcomeName=me.name??'';const x=await this.api.get<any>('/dashboard');this.cards=Object.entries(x.cards?.[0]??{}).map(([label,value])=>({label:this.cardLabel(label),value}));this.chart=this.completeWeek(x.chart??[]);this.recent=x.recent??[];}catch(e){this.error=msg(e);}finally{this.loading=false;this.cdr.detectChanges();}}completeWeek(rows:any[]){const names=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];const english=['monday','tuesday','wednesday','thursday','friday','saturday','sunday'];const week=names.map((diaSemana,index)=>({numeroDia:index+1,diaSemana,totalTickets:0}));for(const row of rows){const label=String(row.diaSemana??row.DiaSemana??'').toLowerCase();const byName=names.findIndex(day=>day.toLowerCase()===label);const byEnglish=english.indexOf(label);const index=Number(row.numeroDia??row.NumeroDia)-1;const dayIndex=index>=0&&index<7?index:(byName>=0?byName:byEnglish);if(dayIndex>=0&&dayIndex<7)week[dayIndex].totalTickets=Number(row.totalTickets??row.TotalTickets??row.cantidad??row.Cantidad??0);}return week;}cardLabel(key:string){return ({ticketsTotales:'Tickets totales del mes',usuariosActivos:'Usuarios activos',departamentosActivos:'Áreas activas',ticketsSinAsignar:'Tickets sin asignar',ticketsAsignados:'Tickets asignados',ticketsSinDepartamento:'Tickets sin área',ticketsConDepartamento:'Tickets con área'} as any)[key]??key;}bar(x:any){const count=Number(x.totalTickets??0);const max=Math.max(1,...this.chart.map(row=>Number(row.totalTickets??0)));return Math.max(5,Math.min(100,count/max*100));} }

@Component({selector:'tickets-page',standalone:true,imports:[CommonModule,FormsModule],styleUrls:['./legacy-styles/ticket-list.css','./legacy-styles/ticket-manager.css','./legacy-styles/todoslostickets.css','./legacy-styles/ticket-detail.css'],template:`
<section class="container mt-4">
  <div class="d-flex justify-content-between align-items-center mb-3"><h2>{{roleId===4?'Bandeja de Asignación':roleId===2?'Mis Tickets Asignados':'Mis Tickets'}}</h2><a *ngIf="roleId===1||roleId===3" class="btn btn-success" routerLink="/nuevo-ticket">Crear Ticket</a></div>
  <div class="alert alert-danger" *ngIf="error">{{error}}</div>
  <ul class="nav nav-tabs mb-3"><li class="nav-item" *ngFor="let f of filters"><button class="nav-link" [class.active]="filter===f" (click)="filter=f">{{f}}</button></li></ul>
  <div class="row"><div class="col-sm-6 col-md-4 col-lg-3 mb-4" *ngFor="let t of visibleTickets"><article class="card h-100 text-start text-dark mb-2 ticket-manager-card" (click)="detail(t.id_Ticket)"><div class="card-body"><h5 class="card-title">{{t['título']}}</h5><p class="card-text mb-1">{{t['descripción']}}</p><div class="mb-2"><span class="badge bg-primary me-1">{{t.prioridad}}</span><span class="badge bg-secondary">{{t.estado}}</span></div><small class="text-muted">#{{t.id_Ticket}} – {{t.fecha|date:'dd/MM/yyyy'}}</small><br><small class="text-muted">Solicitante: {{t.usuario}}</small><br><small class="text-muted">Agente: {{t.agente}}</small><div class="mt-2" *ngIf="roleId===4&&!t.agenteId" (click)="$event.stopPropagation()"><select class="form-select form-select-sm mb-2" [(ngModel)]="assignment[t.id_Ticket]"><option [ngValue]="undefined">Selecciona un agente</option><option *ngFor="let agent of agents" [ngValue]="agent.id">{{agent.nombre}} {{agent.apellidos}}</option></select><button class="btn btn-sm btn-primary" [disabled]="!assignment[t.id_Ticket]" (click)="assign(t.id_Ticket,assignment[t.id_Ticket])">Asignar al agente</button></div></div></article></div></div>
  <div class="modal fade show d-block ticket-detail-modal" *ngIf="selected" role="dialog" aria-modal="true" [attr.aria-label]="'Detalles del ticket '+selected.id_Ticket">
    <div class="modal-dialog modal-dialog-centered modal-lg ticket-detail-dialog"><div class="modal-content">
      <header class="modal-header ticket-detail-header"><div><span class="ticket-detail-kicker">DETALLE DEL TICKET</span><h4 class="modal-title">#{{selected.id_Ticket}} · {{selected['título']}}</h4></div><button type="button" class="btn-close" aria-label="Cerrar" (click)="selected=null"></button></header>
      <div class="modal-body ticket-detail-body">
        <div class="ticket-detail-layout">
          <main class="ticket-detail-main">
            <section class="detail-panel description-panel"><div class="detail-panel-heading"><span class="detail-icon"><i class="bi bi-card-text"></i></span><h6>Descripción</h6></div><p class="ticket-description">{{selected['descripción']}}</p></section>
            <section class="detail-panel followup-panel" *ngIf="roleId===2&&Number(selected.agenteId)===userId"><div class="detail-panel-heading"><span class="detail-icon"><i class="bi bi-chat-left-text"></i></span><h6>Seguimiento</h6></div><label class="form-label" for="followup-message">Agrega una actualización</label><textarea id="followup-message" class="form-control" rows="3" maxlength="300" [(ngModel)]="followupText" placeholder="Describe las acciones realizadas o los avances..."></textarea><div class="followup-submit"><small>{{followupText.length}}/300 caracteres</small><button class="btn btn-primary" [disabled]="!followupText.trim()||followupBusy" (click)="sendFollowup()"><i class="bi bi-plus-lg me-1"></i>{{followupBusy?'Guardando…':'Agregar seguimiento'}}</button></div>
              <div class="followup-history" *ngIf="followups.length"><h6>Historial</h6><article class="followup-entry" *ngFor="let item of followups"><div class="followup-entry-meta"><b>{{item.agente}}</b><time>{{item.fecha|date:'short'}}</time></div><p>{{item.mensaje}}</p></article></div><p class="followup-empty" *ngIf="!followups.length">Aún no hay actualizaciones.</p>
            </section>
          </main>
          <aside class="ticket-detail-aside">
            <section class="detail-panel status-panel"><span class="detail-label">ESTADO</span><span class="badge ticket-state-badge" [ngClass]="{'state-resolved':selected.estado==='Resuelto','state-pending':selected.estado==='Pendiente','state-active':selected.estado==='Activo','state-cancelled':selected.estado==='Cancelado'}">{{selected.estado}}</span><div class="detail-meta-row"><span>Prioridad</span><b>{{selected.prioridad||'—'}}</b></div><div class="detail-meta-row"><span>Área que recibe</span><b>{{selected.departamento||'—'}}</b></div><div class="detail-meta-row"><span>Responsable</span><b>{{selected.agente||'Sin asignar'}}</b></div><div class="detail-meta-row"><span>Fecha</span><b>{{selected.fecha|date:'dd/MM/yyyy'}}</b></div></section>
            <section class="detail-panel requester-panel" *ngIf="roleId===2"><div class="detail-panel-heading"><span class="detail-icon"><i class="bi bi-person"></i></span><h6>Solicitante</h6></div><div class="requester-name">{{selected.solicitante||'—'}}</div><a class="requester-email" *ngIf="selected.correoSolicitante" [href]="'mailto:'+selected.correoSolicitante">{{selected.correoSolicitante}}</a><div class="requester-area"><span>Área de su cuenta</span><b>{{selected.areaOrigenUsuario||'No disponible'}}</b></div></section>
            <section class="detail-panel agent-controls" *ngIf="roleId===2&&Number(selected.agenteId)===userId"><label class="form-label" for="ticket-status">Actualizar estado</label><select id="ticket-status" class="form-select" [(ngModel)]="newStatus"><option [ngValue]="1">Activo</option><option [ngValue]="2">Pendiente</option><option [ngValue]="3">Resuelto</option><option [ngValue]="4">Cancelado</option></select><button class="btn btn-outline-primary w-100 mt-2" (click)="updateStatus()">Guardar estado</button></section>
            <section class="detail-panel evidence-panel" *ngIf="selected.ruta||roleId===2&&Number(selected.agenteId)===userId&&Number(selected.estadoId)===3"><div class="detail-panel-heading"><span class="detail-icon"><i class="bi bi-file-earmark-pdf"></i></span><h6>Evidencia</h6></div><a *ngIf="selected.ruta" class="btn btn-outline-secondary w-100" [href]="selected.ruta" target="_blank" rel="noopener">Ver PDF</a><ng-container *ngIf="roleId===2&&Number(selected.agenteId)===userId&&Number(selected.estadoId)===3"><p class="evidence-hint" *ngIf="!selected.ruta">Adjunta el PDF que documenta la resolución.</p><label class="form-label" for="ticket-evidence">{{selected.ruta?'Reemplazar PDF':'PDF de resolución'}}</label><input id="ticket-evidence" type="file" class="form-control" accept="application/pdf,.pdf" (change)="upload($event)"></ng-container></section>
          </aside>
        </div>
        <div class="alert alert-danger mt-3 mb-0" *ngIf="error">{{error}}</div><div class="alert alert-success mt-3 mb-0" *ngIf="message">{{message}}</div>
      </div>
    </div></div>
  </div><div class="modal-backdrop fade show ticket-detail-backdrop" *ngIf="selected" (click)="selected=null"></div>
</section>`})
class TicketsComponent implements OnInit {private api=inject(ApiService);tickets:any[]=[];agents:any[]=[];assignment:any={};followups:any[]=[];followupText='';followupBusy=false;selected:any;error='';message='';roleId=0;userId=0;rating=0;newStatus=1;Number=Number;filter='Todos';filters=['Todos','Sin asignar','Asignados a mí','Activos','Pendientes','Resueltos','Cancelados','Por prioridad'];get visibleTickets(){const rows=this.tickets.filter(t=>this.filter==='Todos'||(this.filter==='Sin asignar'&&!t.agenteId)||(this.filter==='Asignados a mí'&&Number(t.agenteId)===this.userId)||(this.filter==='Asignados'&&Number(t.agenteId)>0)||(this.filter==='Activos'&&t.estado==='Activo')||(this.filter==='Pendientes'&&t.estado==='Pendiente')||(this.filter==='Resueltos'&&t.estado==='Resuelto')||(this.filter==='Cancelados'&&t.estado==='Cancelado'));return this.filter==='Por prioridad'?rows.sort((a,b)=>(b.prioridadArea??0)-(a.prioridadArea??0)):rows;}async ngOnInit(){try{const [rows,me]=await Promise.all([this.api.get<any[]>('/tickets'),this.api.get<any>('/auth/me')]);this.tickets=rows;this.roleId=Number(me.roleId);this.userId=Number(me.id);if(this.roleId===4){this.agents=await this.api.get<any[]>('/agents');this.filters=['Todos','Sin asignar','Asignados','Activos','Pendientes','Resueltos','Cancelados','Por prioridad'];}else if(this.roleId===2)this.filters=['Todos','Activos','Pendientes','Resueltos','Cancelados','Por prioridad'];}catch(e){this.error=msg(e);}}async detail(id:number){const [detail,followups]=await Promise.all([this.api.get<any>(`/tickets/${id}`),this.roleId===2?this.api.get<any[]>(`/tickets/${id}/followups`):Promise.resolve([])]);const list=this.tickets.find(t=>Number(t.id_Ticket)===id);this.selected={...list,...detail,estado:list?.estado??detail.estado,estadoId:Number(detail.estado)};this.followups=followups;this.followupText='';this.newStatus=this.selected.estadoId||1;this.rating=Number(this.selected.calif)||0;}async updateStatus(){try{await this.api.put(`/tickets/${this.selected.id_Ticket}/status`,{statusId:this.newStatus});this.message='Estado actualizado.';this.tickets=await this.api.get<any[]>('/tickets');const row=this.tickets.find(t=>Number(t.id_Ticket)===Number(this.selected.id_Ticket));if(row)this.selected={...this.selected,...row,estadoId:Number(this.newStatus)};}catch(e){this.error=msg(e);}}async sendFollowup(){const message=this.followupText.trim();if(!message)return;this.followupBusy=true;this.error='';try{await this.api.post(`/tickets/${this.selected.id_Ticket}/followups`,{message});this.followupText='';this.followups=await this.api.get<any[]>(`/tickets/${this.selected.id_Ticket}/followups`);this.message='Seguimiento guardado.';}catch(e){this.error=msg(e);}finally{this.followupBusy=false;}}async assign(id:number,agentId:number){try{await this.api.post(`/tickets/${id}/assign`,{agentId:Number(agentId)});this.message='Ticket asignado al agente.';this.tickets=await this.api.get<any[]>('/tickets');}catch(e){this.error=msg(e);}}async rate(){await this.api.put(`/tickets/${this.selected.id_Ticket}/rating`,{rating:this.rating});this.message='Calificación guardada.';}async upload(event:any){const file=event.target.files?.[0];if(!file)return;const data=new FormData();data.append('file',file);try{const result=await fetch(`/api/tickets/${this.selected.id_Ticket}/evidence`,{method:'POST',body:data,credentials:'include'});if(!result.ok)throw new Error('No se pudo cargar el PDF.');this.message='Evidencia cargada.';await this.detail(this.selected.id_Ticket);}catch(e){this.error=msg(e);}} }

@Component({selector:'new-ticket-page',standalone:true,imports:[CommonModule,FormsModule],styleUrls:['./legacy-styles/crearticket.css','./legacy-styles/ticket-list.css'],template:`
<section class="container mt-4"><div class="row"><div class="col-md-8"><div class="alert alert-info" *ngIf="message">{{message}}</div><article class="ticket-card d-flex mb-3 border rounded" *ngFor="let t of tickets" (click)="detail(t.id_Ticket)"><header class="card-header d-flex flex-column align-items-center"><div class="rounded-circle d-flex align-items-center justify-content-center mb-1 status-activo" style="width:60px;height:60px"><span class="fw-bold">{{t.id_Ticket}}</span></div></header><div class="card-body"><h5>{{t['título']}}</h5><p>Área: {{t.departamento}}</p><div><span class="badge bg-info me-2">{{t.prioridad}}</span><span class="badge bg-secondary">{{t.estado}}</span></div><small class="text-muted">{{t.fecha|date:'shortDate'}} · {{t.agente}}</small></div></article><p *ngIf="!tickets.length">No hay tickets actualmente.</p></div><div class="col-md-4 d-flex align-items-start justify-content-center"><button class="btn btn-primary mt-2 w-75" (click)="showForm=true">Crear Ticket</button></div></div>
<div class="modal fade show d-block" *ngIf="showForm" tabindex="-1"><div class="modal-dialog" style="max-width:45%"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Crear Nuevo Ticket</h5><button class="btn-close" [disabled]="saving" (click)="showForm=false"></button></div><div class="modal-body"><div class="card-header text-black text-center"><h4>Envíe una nueva solicitud</h4></div><form class="card-body" (ngSubmit)="save()"><div class="mb-2"><label class="form-label">Título de la Solicitud</label><input class="form-control" maxlength="70" [(ngModel)]="form.title" name="title" required></div><div class="mb-2"><label class="form-label">Área</label><select class="form-select" [(ngModel)]="form.departmentId" name="area" required><option [ngValue]="0">Seleccione...</option><option *ngFor="let a of areas" [ngValue]="a.id_Departamento">{{a.dep_Nombre}}</option></select></div><div class="mb-2"><label class="form-label">Descripción</label><textarea class="form-control" rows="5" maxlength="350" [(ngModel)]="form.description" name="description" required></textarea></div><div class="modal-footer"><button type="button" class="btn btn-secondary" [disabled]="saving" (click)="showForm=false">Cancelar</button><button type="submit" class="btn btn-primary" [disabled]="saving">{{saving?'Enviando…':'Enviar Ticket'}}</button></div></form></div></div></div></div><div class="modal-backdrop fade show" *ngIf="showForm" (click)="!saving&&(showForm=false)"></div>
<div class="modal fade show d-block" *ngIf="selected" tabindex="-1"><div class="modal-dialog" style="max-width:50%"><div class="modal-content"><div class="modal-header bg-primary text-white"><h5>Detalles del Ticket: {{selected.id_Ticket}}</h5><button class="btn-close" (click)="selected=null"></button></div><div class="modal-body"><p><b>Título:</b> {{selected['título']}}</p><p><b>Área:</b> {{selected.departamento}}</p><p><b>Descripción:</b> {{selected['descripción']}}</p><p><b>Responsable:</b> {{selected.agente}}</p><p *ngIf="selected.ruta"><a [href]="selected.ruta" target="_blank">Ver Evidencia</a></p><div *ngIf="selected.estado==='Resuelto'"><p *ngIf="ratingSaved" class="text-success">Este ticket ya fue calificado: {{rating}} / 5</p><ng-container *ngIf="!ratingSaved"><label>Calificación</label><select class="form-select" [(ngModel)]="rating"><option [ngValue]="1">1 estrella</option><option [ngValue]="2">2 estrellas</option><option [ngValue]="3">3 estrellas</option><option [ngValue]="4">4 estrellas</option><option [ngValue]="5">5 estrellas</option></select><button class="btn btn-primary mt-2" (click)="rate()">Guardar calificación</button></ng-container></div></div><div class="modal-footer" *ngIf="selected.estado!=='Resuelto'"><button class="btn btn-danger btn-sm" (click)="cancel()">Cancelar Ticket</button></div></div></div></div><div class="modal-backdrop fade show" *ngIf="selected" (click)="selected=null"></div></section>`})
class NewTicketComponent implements OnInit {private api=inject(ApiService);areas:any[]=[];tickets:any[]=[];selected:any=null;rating=0;ratingSaved=false;showForm=false;saving=false;message='';form:any={title:'',description:'',departmentId:0};async ngOnInit(){try{const [lookups,tickets]=await Promise.all([this.api.get<any>('/lookups'),this.api.get<any[]>('/tickets')]);this.areas=lookups.departments;this.tickets=tickets;}catch(e){this.message=msg(e);}}async load(){this.tickets=await this.api.get<any[]>('/tickets');}async save(){if(this.saving)return;this.saving=true;this.message='';try{await this.api.post('/tickets',this.form);this.form={title:'',description:'',departmentId:0};this.showForm=false;this.message='Ticket enviado.';void this.load().catch(()=>{});}catch(e){this.message=msg(e);}finally{this.saving=false;}}async detail(id:number){const d=await this.api.get<any>(`/tickets/${id}`);this.selected={...d,...this.tickets.find(x=>x.id_Ticket===id)};this.rating=Number(this.selected.calif||this.selected.tick_Calificacion)||0;this.ratingSaved=this.rating>0;}async cancel(){await this.api.put(`/tickets/${this.selected.id_Ticket}/status`,{statusId:4});this.selected=null;await this.load();}async rate(){try{await this.api.put(`/tickets/${this.selected.id_Ticket}/rating`,{rating:this.rating});this.ratingSaved=true;this.message='Calificación registrada.';}catch(e){this.message=msg(e);}}}

@Component({selector:'areas-page',standalone:true,imports:[CommonModule,FormsModule],styleUrls:['./legacy-styles/areas.css'],template:`
<section><div class="row align-items-center mb-3"><div class="col"><h2>Gestión de Áreas</h2></div><div class="col text-end"><button class="btn btn-success" (click)="editing=null;form={name:'',priorityId:1}">Agregar</button></div></div><div class="row" id="areaList"><div class="col-md-4 mb-3" *ngFor="let a of areas"><div class="card text-dark bg-light"><div class="card-body"><h5 class="card-title">Área: {{a.area}}</h5><p class="card-text">Prioridad: {{a.prioridad}}</p><div class="d-flex gap-2"><button class="btn btn-edit" (click)="edit(a)"><i class="bi bi-pencil-square"></i></button><button class="btn btn-danger" (click)="remove(a.id)"><i class="bi bi-trash"></i></button></div></div></div></div></div><div class="modal-content p-3 mt-3" *ngIf="form"><h5>{{editing?'Editar':'Agregar'}} Área</h5><label class="form-label">Nombre:</label><input class="form-control mb-2" [(ngModel)]="form.name"><label class="form-label">Prioridad:</label><select class="form-select mb-3" [(ngModel)]="form.priorityId"><option *ngFor="let p of priorities" [ngValue]="p.id_Prioridad">{{p.pri_Descripcion}}</option></select><div><button class="btn btn-primary me-2" (click)="save()">Guardar</button><button class="btn btn-secondary" (click)="form=null">Cancelar</button></div></div><p class="text-success">{{message}}</p></section>`})
class AreasComponent implements OnInit {private api=inject(ApiService);areas:any[]=[];priorities:any[]=[];form:any=null;editing:number|null=null;message='';async ngOnInit(){await this.load();const x=await this.api.get<any>('/lookups');this.priorities=x.priorities;}async load(){this.areas=await this.api.get<any[]>('/areas');}edit(a:any){this.editing=a.id;this.form={name:a.area,priorityId:this.priorities.find(p=>p.pri_Descripcion===a.prioridad)?.id_Prioridad??1};}async save(){try{if(this.editing)await this.api.put(`/areas/${this.editing}`,this.form);else await this.api.post('/areas',this.form);this.form=null;this.editing=null;await this.load();}catch(e){this.message=msg(e);}}async remove(id:number){if(confirm('¿Eliminar esta área?')){await this.api.delete(`/areas/${id}`);await this.load();}} }

@Component({selector:'users-page',standalone:true,imports:[CommonModule,FormsModule],styleUrls:['./legacy-styles/usuarios.css'],template:`
<section><div class="d-flex justify-content-between align-items-center mb-3"><h2>Gestionar Usuarios</h2><button class="btn btn-success" (click)="editing=null;form={name:'',lastName:'',email:'',phone:'',departmentId:0,roleId:1,status:'Activo',password:''}">Agregar</button></div><div class="row g-2 mb-3"><div class="col-md-3"><input class="form-control" placeholder="Buscar usuarios..." [(ngModel)]="filters.name"></div><div class="col-md-2"><input class="form-control" placeholder="Correo" [(ngModel)]="filters.email"></div><div class="col-md-2"><select class="form-select" multiple aria-label="Filtrar por áreas" [(ngModel)]="filters.departmentIds"><option *ngFor="let a of areas" [value]="a.id_Departamento">{{a.dep_Nombre}}</option></select></div><div class="col-md-2"><select class="form-select" multiple aria-label="Filtrar por roles" [(ngModel)]="filters.roleIds"><option *ngFor="let r of roles" [value]="r.idRol">{{r.rol_Descripcion}}</option></select></div><div class="col-md-1"><select class="form-select" aria-label="Estado" [(ngModel)]="filters.status"><option value="">Estado</option><option>Activo</option><option>Inactivo</option></select></div><div class="col-md-2"><button class="btn btn-primary me-1" (click)="load()">Filtrar</button><button class="btn btn-outline-secondary" (click)="clearFilters()">Limpiar</button></div></div><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Nombre</th><th>Correo</th><th>Teléfono</th><th>Rol</th><th>Área</th><th>Estado</th><th></th></tr></thead><tbody><tr *ngFor="let u of users"><td>{{u.nombre}} {{u.apellidos}}</td><td>{{u.email}}</td><td>{{u['teléfono']||u.telefono}}</td><td>{{u.rol}}</td><td>{{u['área']}}</td><td>{{u.status}}</td><td><button class="btn btn-sm btn-outline-primary me-1" (click)="edit(u)">Editar</button><button class="btn btn-sm btn-danger" (click)="remove(u.id)">Eliminar</button></td></tr></tbody></table></div><div class="card p-3" *ngIf="form"><h5>{{editing?'Editar':'Registrar'}} usuario</h5><div class="row g-2"><div class="col-md-6"><input class="form-control" placeholder="Nombre" [(ngModel)]="form.name"></div><div class="col-md-6"><input class="form-control" placeholder="Apellidos" [(ngModel)]="form.lastName"></div><div class="col-md-6"><input class="form-control" placeholder="Correo" [(ngModel)]="form.email"></div><div class="col-md-6"><input class="form-control" placeholder="Teléfono" [(ngModel)]="form.phone"></div><div class="col-md-4"><select class="form-select" [(ngModel)]="form.departmentId"><option *ngFor="let a of areas" [ngValue]="a.id_Departamento">{{a.dep_Nombre}}</option></select></div><div class="col-md-4"><select class="form-select" [(ngModel)]="form.roleId"><option *ngFor="let r of roles" [ngValue]="r.idRol">{{r.rol_Descripcion}}</option></select></div><div class="col-md-4"><select class="form-select" [(ngModel)]="form.status"><option>Activo</option><option>Inactivo</option></select></div><div class="col-md-12" *ngIf="!editing"><input class="form-control" type="password" placeholder="Contraseña" [(ngModel)]="form.password" required></div></div><div class="mt-3"><button *ngIf="editing" class="btn btn-warning me-2" (click)="resetPassword()">Restablecer contraseña</button><button class="btn btn-primary me-2" (click)="save()">Guardar</button><button class="btn btn-secondary" (click)="form=null">Cancelar</button></div></div><p class="text-danger">{{message}}</p></section>`})
class UsersComponent implements OnInit {private api=inject(ApiService);users:any[]=[];areas:any[]=[];roles:any[]=[];form:any=null;editing:number|null=null;message='';filters:any={name:'',email:'',status:'',departmentIds:[] as string[],roleIds:[] as string[]};async ngOnInit(){const x=await this.api.get<any>('/lookups');this.areas=x.departments;this.roles=x.roles;await this.load();}async load(){const q=new URLSearchParams();for(const key of ['name','email','status'])if(this.filters[key])q.set(key,this.filters[key]);if(this.filters.departmentIds.length)q.set('departmentIds',this.filters.departmentIds.join(','));if(this.filters.roleIds.length)q.set('roleIds',this.filters.roleIds.join(','));const query=q.toString();this.users=await this.api.get<any[]>(`/users${query?'?'+query:''}`);}clearFilters(){this.filters={name:'',email:'',status:'',departmentIds:[],roleIds:[]};this.load();}edit(u:any){this.editing=u.id;this.form={name:u.nombre,lastName:u.apellidos,email:u.email,phone:u['teléfono']||u.telefono,departmentId:u.idArea,roleId:this.roles.find(r=>r.rol_Descripcion===u.rol)?.idRol??1,status:u.status,password:''};}async save(){try{if(this.editing)await this.api.put(`/users/${this.editing}`,this.form);else await this.api.post('/users',this.form);this.form=null;this.editing=null;await this.load();}catch(e){this.message=msg(e);}}async resetPassword(){if(!this.editing)return;const result=await this.api.post<any>(`/users/${this.editing}/reset-password`);alert(`La nueva contraseña temporal es: ${result.temporaryPassword}`);}async remove(id:number){if(confirm('¿Eliminar usuario?')){await this.api.delete(`/users/${id}`);await this.load();}} }

@Component({selector:'calendar-page',standalone:true,imports:[CommonModule,FormsModule],styleUrls:['./legacy-styles/calendar.css'],template:`<section><div class="calendar-container"><div class="calendar-header"><div class="calendar-navigation"><button class="nav-button" (click)="changeMonth(-1)" title="Mes anterior">‹</button><h2 class="calendar-title">{{monthTitle}}</h2><button class="nav-button" (click)="changeMonth(1)" title="Mes siguiente">›</button></div><button class="btn-agregar-evento" (click)="newEvent()">Agregar Evento</button></div><div class="day-header"><div class="day-name" *ngFor="let name of dayNames">{{name}}</div></div><div class="calendar-grid"><div class="calendar-cell empty" *ngFor="let blank of blanks"></div><div class="calendar-cell" *ngFor="let day of days" [class.hoy]="day.today" (click)="openDay(day.date)"><div class="day-number">{{day.number}}</div><span class="event-badge" *ngFor="let e of day.events" [style.background-color]="e.color" [title]="e.evento_Descripcion">{{e.evento_Titulo}}</span></div></div></div><div class="card p-3 mt-3" *ngIf="selectedDate"><h4>Eventos del {{selectedDate|date:'longDate'}}</h4><article *ngFor="let e of selectedEvents" class="border-bottom py-2"><strong>{{e.evento_Titulo}}</strong> <span>{{e.fecha_Inicio|date:'shortTime'}} – {{e.fecha_Fin|date:'shortTime'}}</span><p>{{e.evento_Descripcion}}</p><ng-container *ngIf="canEdit(e)"><ng-container *ngIf="canEdit(e)"><button class="btn btn-sm btn-outline-primary me-1" (click)="edit(e)">Editar</button><button class="btn btn-sm btn-danger" (click)="remove(e.id_Evento)">Eliminar</button></ng-container></ng-container></article><button class="btn btn-link" (click)="selectedDate=null">Cerrar</button></div><div id="modalAgregarEvento" class="modal" [style.display]="showForm?'block':'none'"><div class="form-container"><h2 class="form-title">{{editing?'Editar Evento':'Agregar Nuevo Evento'}}</h2><p class="text-danger" *ngIf="error">{{error}}</p><div class="form-grid"><div class="form-group"><label class="form-label">Título del evento</label><input class="form-control" [(ngModel)]="form.title" placeholder="Título del evento"></div><div class="form-group"><label class="form-label">Color del evento</label><input type="color" class="form-control" [(ngModel)]="form.color"></div><div class="form-group"><label class="form-label">Fecha y hora de inicio</label><input type="datetime-local" class="form-control" [(ngModel)]="form.start"></div><div class="form-group"><label class="form-label">Fecha y hora de fin</label><input type="datetime-local" class="form-control" [(ngModel)]="form.end"></div><div class="form-group"><label class="form-label">Descripción</label><textarea class="form-control" rows="4" [(ngModel)]="form.description"></textarea></div><div class="form-group"><label><input type="checkbox" [(ngModel)]="form.allDay"> Todo el día</label></div></div><div class="btn-group"><button class="btn-guardar" (click)="save()">{{editing?'Guardar Cambios':'Guardar Evento'}}</button><button class="btn-cancelar" (click)="showForm=false">Cancelar</button></div></div></div></section>`})
class CalendarComponent implements OnInit {private api=inject(ApiService);events:any[]=[];areas:any[]=[];showForm=false;editing:number|null=null;roleId=0;userId=0;error='' ;currentDate=new Date();dayNames=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];days:any[]=[];blanks:number[]=[];selectedDate:Date|null=null;selectedEvents:any[]=[];form:any={title:'',description:'',start:'',end:'',allDay:false,color:'#fec526',departmentId:null};get monthTitle(){return this.currentDate.toLocaleDateString('es-MX',{month:'long',year:'numeric'});}async ngOnInit(){const me=await this.api.get<any>('/auth/me');this.roleId=Number(me.roleId);this.userId=Number(me.id);this.events=await this.api.get<any[]>('/calendar');this.areas=(await this.api.get<any>('/lookups')).departments;this.render();}canEdit(e:any){return this.roleId===3||Number(e.fk_Usuario)===this.userId;}render(){const year=this.currentDate.getFullYear(),month=this.currentDate.getMonth();const first=new Date(year,month,1);this.blanks=Array.from({length:(first.getDay()+6)%7},(_,i)=>i);const today=new Date();this.days=Array.from({length:new Date(year,month+1,0).getDate()},(_,i)=>{const date=new Date(year,month,i+1);return {number:i+1,date,today:date.toDateString()===today.toDateString(),events:this.events.filter(e=>new Date(e.fecha_Inicio).toDateString()===date.toDateString())};});}changeMonth(delta:number){this.currentDate=new Date(this.currentDate.getFullYear(),this.currentDate.getMonth()+delta,1);this.render();}openDay(date:Date){this.selectedDate=date;this.selectedEvents=this.events.filter(e=>new Date(e.fecha_Inicio).toDateString()===date.toDateString());}newEvent(){this.editing=null;this.form={title:'',description:'',start:'',end:'',allDay:false,color:'#fec526',departmentId:null};this.showForm=true;}edit(e:any){this.editing=e.id_Evento;this.form={title:e.evento_Titulo,description:e.evento_Descripcion,start:e.fecha_Inicio?.slice(0,16),end:e.fecha_Fin?.slice(0,16),allDay:e.todo_El_Dia,color:e.color,departmentId:e.fk_Departamento};this.showForm=true;}async save(){this.error='';if(!this.form.title?.trim()||!this.form.start||!this.form.end||new Date(this.form.start)>new Date(this.form.end)){this.error='Escribe un título y un rango válido de fecha y hora.';return;}const body={...this.form,start:this.form.start,end:this.form.end};try{if(this.editing)await this.api.put(`/calendar/${this.editing}`,body);else await this.api.post('/calendar',body);this.events=await this.api.get<any[]>('/calendar');this.render();this.showForm=false;}catch(e){this.error=msg(e);}}async remove(id:number){await this.api.delete(`/calendar/${id}`);this.events=await this.api.get<any[]>('/calendar');this.render();this.selectedEvents=this.events.filter(e=>this.selectedDate&&new Date(e.fecha_Inicio).toDateString()===this.selectedDate.toDateString());}}

@Component({selector:'stats-page',standalone:true,imports:[CommonModule,FormsModule],styleUrls:['./legacy-styles/statistics.css'],template:`
<section class="container-fluid"><header class="page-header container"><div class="profile-title"><h1>Panel de Control</h1><span class="text-muted small">{{rangeLabel}}</span></div><div class="global-date-filter d-flex flex-wrap gap-4 align-items-start"><div class="d-flex flex-column"><span class="fw-bold mb-2">Filtros</span><div class="d-flex flex-wrap gap-2"><button class="btn btn-sm custom-range" [class.active]="preset==='today'" (click)="setPreset('today')">Hoy</button><button class="btn btn-sm custom-range" [class.active]="preset==='week'" (click)="setPreset('week')">Esta semana</button><button class="btn btn-sm custom-range" [class.active]="preset==='month'" (click)="setPreset('month')">Este mes</button><button class="btn btn-sm custom-range" [class.active]="preset==='year'" (click)="setPreset('year')">Este año</button></div><div class="d-flex gap-2 mt-2"><input aria-label="Fecha inicial" class="form-control form-control-sm" type="date" [(ngModel)]="from"><input aria-label="Fecha final" class="form-control form-control-sm" type="date" [(ngModel)]="to"><button class="btn btn-sm btn-primary" (click)="preset='custom';load()">Aplicar</button></div></div><div class="d-flex flex-column"><span class="fw-bold mb-2">Exportar</span><div class="d-flex gap-2"><button class="btn btn-sm btn-outline-danger" (click)="printReport()"><i class="bi bi-file-earmark-pdf"></i> PDF</button><button class="btn btn-sm btn-outline-success" (click)="exportExcel()"><i class="bi bi-file-earmark-excel"></i> Excel</button></div></div></div></header>
<div id="resumen-tarjetas" class="row mb-4 g-3"><div class="col-md-4 col-sm-6" *ngFor="let x of general;let i=index"><div class="stat-card" [class.card-total]="i===0" [class.card-resueltos]="i===1" [class.card-calificacion]="i===2"><h3><i class="bi" [class.bi-ticket-detailed]="i===0" [class.bi-check-circle]="i===1" [class.bi-star-fill]="i===2"></i> {{x.label}}</h3><div class="value">{{x.value}}</div></div></div></div>
<div class="row mb-4 g-3"><div class="col-lg-8"><div class="chart-card shadow-sm"><div class="chart-header mb-3"><h3 class="chart-title mb-1">Evolución de Tickets Creados</h3><p class="chart-description text-muted small mb-0">Muestra la cantidad de tickets creados según el período seleccionado.</p></div><div class="chart-container" style="height:300px"><div class="bar-chart"><div class="bar-column" *ngFor="let x of byMonth"><span>{{x.cantidad}}</span><div class="bar-fill" [style.height.%]="scale(x.cantidad,byMonth)"></div><small>{{x.label}}</small></div></div></div><div class="chart-legend mt-2 text-center"><span class="badge badge-tickets">● Tickets creados</span></div></div></div>
<div class="col-lg-4"><div class="chart-card shadow-sm"><h3 class="chart-title">Distribución por estado</h3><p class="chart-description text-muted small">Porcentaje de tickets según su estado actual</p><div class="status-chart"><div class="status-row" *ngFor="let x of byStatus"><span>{{x.estado}}</span><div class="progress"><div class="progress-bar" [style.width.%]="x.porcentaje">{{x.porcentaje}}%</div></div><b>{{x.cantidad}}</b></div></div></div></div></div>
<div class="row mb-4 g-3"><div class="col-lg-6"><div class="chart-card"><h2>Calificación Promedio por Área</h2><p class="chart-description text-muted small">Evaluación promedio recibida por cada área</p><div class="horizontal-chart-row" *ngFor="let x of ratings"><span>{{x.departamento}}</span><div class="progress"><div class="progress-bar" [style.width.%]="Number(x.calificacionPromedio)*20">{{x.calificacionPromedio|number:'1.1-1'}} / 5</div></div></div></div></div><div class="col-lg-6"><div class="chart-card"><h2>Tickets por Área remitente</h2><p class="chart-description text-muted small">Distribución de tickets según el área que los generó</p><div class="horizontal-chart-row" *ngFor="let x of byArea"><span>{{x.departamento}}</span><div class="progress"><div class="progress-bar" [style.width.%]="scale(x.cantidadTickets,byArea)">{{x.cantidadTickets}}</div></div></div></div></div></div>
<div class="row"><div class="col-12"><div class="chart-card recent-activity"><h2>Tickets Recientes</h2><div class="table-responsive"><table class="table table-hover align-middle"><thead class="table-header"><tr><th>ID</th><th>Asunto</th><th>Área</th><th>Fecha</th><th>Estado</th><th>Calificación</th></tr></thead><tbody><tr class="table-row" *ngFor="let t of recent"><td class="fw-semibold">{{t.id}}</td><td>{{t.asunto}}</td><td>{{t.area}}</td><td>{{t.fecha}}</td><td><span class="status-badge">{{t.estado}}</span></td><td>{{t.calificacion}}</td></tr><tr *ngIf="!recent.length"><td colspan="6" class="text-center text-muted">No hay tickets recientes para mostrar</td></tr></tbody></table></div></div></div></div></section>`})
class StatisticsComponent implements OnInit {private api=inject(ApiService);general:any[]=[];byMonth:any[]=[];byStatus:any[]=[];ratings:any[]=[];byArea:any[]=[];recent:any[]=[];from='';to='';preset='today';rangeLabel='';Number=Number;async ngOnInit(){this.setPreset('today');}async setPreset(preset:string){const today=new Date(),start=new Date(today);if(preset==='week'){start.setDate(today.getDate()-((today.getDay()+6)%7));}else if(preset==='month')start.setDate(1);else if(preset==='year')start.setMonth(0,1);this.from=this.dateValue(start);this.to=this.dateValue(today);this.preset=preset;await this.load();}private dateValue(d:Date){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}async load(){try{const params=new URLSearchParams({from:this.from,to:this.to});const x=await this.api.get<any>(`/statistics?${params}`);this.general=Object.entries(x.general?.[0]??{}).map(([label,value])=>({label:this.label(label),value}));this.byMonth=(x.byMonth??[]).map((row:any)=>({cantidad:row.cantidad,label:this.periodLabel(row.agrupador)}));this.byStatus=x.byStatus??[];this.ratings=x.ratings??[];this.byArea=x.byArea??[];this.recent=x.recent??[];this.rangeLabel=`${this.from} a ${this.to}`;}catch{}}private label(name:string){return ({totalTickets:'Tickets totales',ticketsResueltos:'Tickets resueltos',calificacionPromedio:'Calificación promedio'} as any)[name]??name;}private periodLabel(value:any){if(!value)return '';const s=String(value);const date=new Date(s);return Number.isNaN(date.getTime())?s:date.toLocaleDateString('es-MX',{day:'2-digit',month:'short'});}scale(value:number,rows:any[]){const max=Math.max(1,...rows.map(x=>Number(x.cantidad??x.cantidadTickets??0)));return Math.max(3,Number(value)/max*100);}async exportExcel(){const params=new URLSearchParams({from:this.from,to:this.to});const response=await fetch(`/api/statistics/export?${params}`,{credentials:'include'});if(!response.ok)return;const link=document.createElement('a');link.href=URL.createObjectURL(await response.blob());link.download='tickets.xlsx';link.click();URL.revokeObjectURL(link.href);}printReport(){window.print();}}

@Component({selector:'profile-page',standalone:true,imports:[CommonModule,FormsModule],styleUrls:['./legacy-styles/editarperfil.css'],template:`<section><h2 class="profile-title">Editar Perfil</h2><div class="alert alert-info" *ngIf="message">{{message}}</div><form class="profile-container" (ngSubmit)="save()"><div class="mb-3"><label class="form-label">Nombre</label><input class="form-control" [(ngModel)]="form.name" name="name" required></div><div class="mb-3"><label class="form-label">Apellidos</label><input class="form-control" [(ngModel)]="form.lastName" name="lastName" required></div><div class="mb-3"><label class="form-label">Correo Electrónico</label><input class="form-control" type="email" [(ngModel)]="form.email" name="email" required></div><div class="mb-3"><label class="form-label">Área</label><select class="form-control" [(ngModel)]="form.departmentId" name="departmentId"><option *ngFor="let a of areas" [ngValue]="a.id_Departamento">{{a.dep_Nombre}}</option></select></div><div class="mb-3"><label class="form-label">Número de Contacto</label><input class="form-control" [(ngModel)]="form.phone" name="phone" required></div><div class="mb-3"><label class="form-label">Estado</label><select class="form-control" [(ngModel)]="form.status" name="status"><option>Activo</option><option>Inactivo</option></select></div><div class="mb-3"><label class="form-label">Contraseña actual</label><input class="form-control" type="password" [(ngModel)]="form.currentPassword" name="currentPassword" placeholder="Solo para cambiar contraseña"></div><div class="mb-3"><label class="form-label">Nueva contraseña</label><input class="form-control" type="password" [(ngModel)]="form.newPassword" name="newPassword"></div><div class="mb-3"><label class="form-label">Confirmar nueva contraseña</label><input class="form-control" type="password" [(ngModel)]="form.confirmPassword" name="confirmPassword"></div><div class="button-container mt-4"><button type="button" class="btn btn-danger me-2" (click)="load()">Cancelar</button><button class="btn btn-primary">Actualizar</button></div></form></section>`})
class ProfileComponent implements OnInit {private api=inject(ApiService);form:any={};areas:any[]=[];message='';async ngOnInit(){await this.load();this.areas=(await this.api.get<any>('/lookups')).departments;}async load(){const p=await this.api.get<any>('/profile');this.form={name:p.nombre,lastName:p.apellidos,email:p.email,phone:p.telefono,departmentId:p.idArea,status:p.status,currentPassword:'',newPassword:'',confirmPassword:''};}async save(){try{await this.api.put('/profile',this.form);this.message='Perfil actualizado.';await this.load();}catch(e){this.message=msg(e);}}}
@Component({selector:'about-page',standalone:true,styleUrls:['./legacy-styles/acercade.css'],template:`<main class="container mt-5"><h2 class="page-title">About</h2><section class="objetivo-section"><h3 class="text-secondary">Objetivo del Proyecto</h3><p class="lead">Diseñar e implementar un sistema integral que permita gestionar las solicitudes de servicio de manera centralizada, con funciones avanzadas para categorizarlas automáticamente y asignarlas dinámicamente a las áreas correspondientes según la disponibilidad de recursos. Este sistema incluirá un módulo de reportes para analizar el rendimiento de las áreas en términos de tiempo de respuesta y carga de trabajo, además de garantizar una experiencia segura y personalizada mediante un sistema eficiente de autenticación y edición de perfiles, optimizando así la gestión interna y mejorando la eficiencia operativa en tiempo real.</p></section><section class="team-section"><h5 class="text-secondary">Integrantes</h5><ul class="list-group list-group-flush"><li class="list-group-item">Guerrero Jimenez Jesee Isaac</li><li class="list-group-item">Martinez Vargas Brianda Aridel</li><li class="list-group-item">Maurio Jimenez Luis Mario</li><li class="list-group-item">Diego Lopez Vargas</li><li class="list-group-item">Danna Paola Guitierrz Mendez</li></ul></section><section class="asesor-section"><h5 class="text-secondary">Asesor del Proyecto</h5><p class="text-muted">José Manuel Hernandez Reyes</p></section><section class="image-section"><div class="img-container"><img src="/assets/Img/Fabrica_Software.jpeg" class="img-fluid" alt="Fábrica de Software"><p class="image-caption">Fábrica de Software</p></div></section></main>`}) class AboutComponent {}

const routes: Routes = [
  { path: '', redirectTo: 'login', pathMatch: 'full' }, { path: 'login', component: LoginComponent },
  { path: 'home', component: DashboardComponent }, { path: 'tickets', component: TicketsComponent },
  { path: 'nuevo-ticket', component: NewTicketComponent }, { path: 'calendario', component: CalendarComponent },
  { path: 'estadisticas', component: StatisticsComponent }, { path: 'usuarios', component: UsersComponent },
  { path: 'areas', component: AreasComponent }, { path: 'perfil', component: ProfileComponent },
  { path: 'acercade', component: AboutComponent }, { path: '**', redirectTo: 'home' }
];

bootstrapApplication(AppComponent, { providers: [provideZoneChangeDetection(), provideRouter(routes), provideHttpClient()] }).catch(error => console.error(error));
